ValidationRule.errorConditionFormula:
AND(
				NOT(ISNULL(SM_AC_start_date__c)),
    OR(
        AND(
            ISPICKVAL(SM_Way_of_AC_Payment__c, 'One payment'),
            NOT(ISNULL(SM_AC_Split_Date__c))
        ),
				    AND(
								    ISPICKVAL(SM_Way_of_AC_Payment__c, 'Fees'),
								    ISNULL(SM_AC_Split_Date__c)
				    )
    )
)
